fn is_odd_at_odd_index(arr: &Vec<usize>) -> bool {
    for (i, &val) in arr.iter().enumerate() {
        // even index must hold an even value, odd index must hold an odd value
        if (i % 2) != (val % 2) {
            return false;
        }
    }
    true
}

